def top_planes(M,k=1,angle_min=3):
    ev,V=np.linalg.eig(M); idx=np.argsort(-np.abs(ev))
    planes=[];info=[]
    for i in idx:
        if ev[i].imag>1e-6 and abs(np.degrees(np.angle(ev[i])))>angle_min:
            Q,_=np.linalg.qr(np.stack([V[:,i].real,V[:,i].imag],1)); planes.append(Q); info.append(ev[i])
            if len(planes)>=k: break
    return planes,info
