def breakpoint(s,lo=30,hi=200):
    y=np.log(s[:hi]); x=np.arange(hi); best=None
    for b in range(lo,hi-20):
        e=0
        for xs,ys in [(x[:b],y[:b]),(x[b:],y[b:])]:
            p=np.polyfit(xs,ys,1); e+=((np.polyval(p,xs)-ys)**2).sum()
        if best is None or e<best[0]: best=(e,b)
    return best[1]
